/* Browser-local route experience. AI requests are isolated in assistant.js. */
(() => {
'use strict';
const D=window.ACCESS_DATA;
const R=window.ACCESS_REAL;
const app=document.querySelector('#app'),dialog=document.querySelector('#dialog');
const paths={search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 4.5 4.5"/>',compass:'<circle cx="12" cy="12" r="9"/><path d="m16 8-2 6-6 2 2-6Z"/>',pin:'<path d="M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0Z"/><circle cx="12" cy="10" r="2.5"/>',route:'<circle cx="6" cy="5" r="2"/><circle cx="18" cy="19" r="2"/><path d="M6 7v6a3 3 0 0 0 3 3h6a3 3 0 0 0 3-3V8a3 3 0 0 0-3-3h-2"/>',heart:'<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/>',message:'<path d="M21 11.5a9 9 0 0 1-9 9c-1.6 0-3-.4-4.3-1L3 21l1.5-4.7A9 9 0 1 1 21 11.5Z"/><path d="M8 10h8M8 14h5"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',back:'<path d="M20 12H4m6-6-6 6 6 6"/>',check:'<path d="m5 12 4 4L19 6"/>',shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9S4 17 4 12V6Z"/><path d="m8 12 3 3 5-6"/>',chair:'<circle cx="12" cy="4" r="2"/><path d="m11 7-1 7h7l3 5M11 10h6M7 11a6 6 0 1 0 8 8"/>',lift:'<rect x="4" y="2" width="16" height="20" rx="2"/><path d="M8 21V10h8v11M12 10v11m-4-5 2-2 2 2m1 0 2 2 2-2"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10v.1"/>',settings:'<path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="3" fill="currentColor" stroke="none"/><circle cx="16" cy="17" r="3" fill="currentColor" stroke="none"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',sound:'<path d="m11 4-6 5H2v6h3l6 5Zm4 4a6 6 0 0 1 0 8m3-11a10 10 0 0 1 0 14"/>',stop:'<rect x="5" y="5" width="14" height="14" rx="2"/>',alert:'<path d="m12 3 10 18H2Z"/><path d="M12 9v5m0 3v.1"/>',leaf:'<path d="M20 3C7 1 1 9 6 16s17 2 14-13ZM4 21 16 8"/>',home:'<path d="m3 10 9-7 9 7v11H3Zm6 11v-8h6v8"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 1v2m0 18v2M1 12h2m18 0h2M4 4l2 2m12 12 2 2M4 20l2-2M18 6l2-2"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',trash:'<path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7m4-7v7"/>',text:'<path d="m3 20 6-16 6 16M5 15h8m3 5 3-9 3 9m-5-3h4"/>',list:'<path d="M8 6h13M8 12h13M8 18h13M3 6h.1M3 12h.1M3 18h.1"/>',door:'<path d="M4 21h16M6 21V3h12v18M14 12h.1"/>'};
const icon=(name)=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${paths[name]||paths.info}</svg>`;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let storageOK=true;
function read(key,fallback){try{const v=localStorage.getItem('accessai:'+key);return v?JSON.parse(v):fallback}catch{storageOK=false;return fallback}}
const rawSaved=read('saved',[]),rawReports=read('reports',[]),rawSettings=read('settings',{});
const state={view:'home',route:'A',position:'platform',scenario:'normal',trip:null,filter:'all',query:'',realId:null,city:'all',saved:Array.isArray(rawSaved)?rawSaved.filter(x=>Object.hasOwn(D.routes,x)):[],reports:Array.isArray(rawReports)?rawReports.filter(x=>x&&typeof x.type==='string'&&typeof x.note==='string').slice(0,100):[],settings:{large:rawSettings?.large===true},rating:null,speaking:false};
const positions={platform:'B2 · 云桥站站台',hall:'B1 · 云桥站站厅',streetA:'地面 · A 出口外',streetC:'地面 · C 出口外',mall:'星河商场入口',hospital:'云桥社区医院门诊入口',park:'云桥公园东入口'};
const scenarios={normal:{name:'设施正常',desc:'体验完整的主路线与分步指引',icon:'check'},e2:{name:'E2 电梯停运',desc:'从站厅切换至 C 出口备用路线',icon:'route'},e1:{name:'E1 电梯停运',desc:'站台出发时没有已核验的替代路线',icon:'alert'},e3:{name:'E3 电梯停运',desc:'影响东入口路线和医院路线',icon:'lift'},southClosed:{name:'商场南入口关闭',desc:'尚在站厅时可改走东入口',icon:'door'},rain:{name:'公园通道积水',desc:'公园路线受阻，其他目的地不受影响',icon:'alert'}};
const facilityCards=[{id:'E1',type:'lift',name:'站台无障碍电梯 E1',sub:'云桥站 · B2 站台 ↔ B1 站厅',asset:'platform',tags:['连接站台与站厅','需过宽闸机'],detail:'站台中部，位于服务标识旁。连接 B2 站台与 B1 站厅。四条演示路线共用此电梯。'},{id:'E2',type:'lift',name:'A 出口电梯 E2',sub:'云桥站 · B1 站厅 ↔ 地面',asset:'elevator',tags:['主路线设施','通往南入口'],detail:'面向站厅服务台，沿右侧 A 出口指示进入电梯通道。出电梯后沿街面通道前往商场南入口。'},{id:'E3',type:'lift',name:'C 出口电梯 E3',sub:'云桥站 · B1 站厅 ↔ 地面',asset:'hall-c',tags:['备用路线设施','通往东入口'],detail:'从站厅服务台沿 C 出口方向，通过宽闸机后前往 E3 电梯。此路径用于绕开 E2。'},{id:'south',type:'entrance',name:'星河商场 · 南入口',sub:'商场 1F · 云桥路一侧',asset:'entrance',tags:['无台阶入口','演示开放 10:00–22:00'],detail:'位于商场南侧，连接 A 出口街面通道。演示设定为无台阶、自动门入口。真实门宽与坡度未采集。'},{id:'east',type:'entrance',name:'星河商场 · 东入口',sub:'商场 1F · 星河步行街一侧',asset:'street',tags:['无台阶入口','备用入口'],detail:'位于商场东侧，连接 C 出口街面通道。演示路线经过路缘坡道，抵达自动门入口。'},{id:'wc',type:'service',name:'商场无障碍卫生间',sub:'星河商场 · 1F 服务台附近',asset:'hall',tags:['信息不足','暂未纳入路线'],detail:'仅展示设施资料不足的状态。具体门宽、转身空间、开放情况与到达路径均待核实，本演示不提供前往该设施的导航。'}];
facilityCards.push({id:'entrance-hospital',type:'entrance',name:'社区医院 · 门诊入口',sub:'云桥社区医院 · 1F',asset:'hospital',tags:['平层入口','院内路径待确认'],detail:'从 C 出口沿演示通道抵达门诊入口，进门后向服务台确认就诊楼层。院内无障碍路线尚未收录。'},{id:'entrance-park',type:'entrance',name:'云桥公园 · 东入口',sub:'云桥公园 · 地面',asset:'park',tags:['平层入口','园内路径未收录'],detail:'从 A 出口沿公园东侧通道抵达入口。积水场景会阻断入口之前的通道，即使入口本身开放也无法走通。'},{id:'path-park',type:'service',name:'公园东侧通道',sub:'A 出口街面 → 公园东入口',asset:'park',tags:['室外通道','注意路面条件'],detail:'演示中的连续室外通道。切换积水场景时，此路段将被标为模拟停用；本示例没有其他可通行的备用路径。'});
function persist(key,value){try{localStorage.setItem('accessai:'+key,JSON.stringify(value));return true}catch{storageOK=false;toast('浏览器无法保存，记录仅保留到本次页面关闭');return false}}
let toastTimer;function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),4200)}
function stopSpeech(){if('speechSynthesis'in window)window.speechSynthesis.cancel();state.speaking=false}
function go(view){stopSpeech();state.view=view;state.query='';render();window.scrollTo({top:0,behavior:'instant'});requestAnimationFrame(()=>document.querySelector('main h1,main h2')?.focus({preventScroll:true}))}
const tag=(text,cls='',ic='')=>`<span class="tag ${cls}">${ic?icon(ic):''}${text}</span>`;
const btn=(label,act,cls='primary',extra='')=>`<button class="btn ${cls}" data-action="${act}" ${extra}>${label}</button>`;
function nav(active,mobile=false){return `<nav class="${mobile?'bottom-nav':'nav'}" aria-label="${mobile?'手机主导航':'主导航'}">${[['home','compass','出行规划'],['real','pin','真实站点'],['facilities','lift','无障碍设施'],['saved','heart','我的收藏'],['reports','message','反馈记录']].map(([v,i,l])=>`<button class="${mobile?'':'nav-btn '}${active===v?'active':''}" data-action="nav" data-view="${v}" ${active===v?'aria-current="page"':''}>${icon(i)}<span>${l}</span>${!mobile&&active===v?'<i class="nav-dot"></i>':''}</button>`).join('')}</nav>`}
function layout(body){const active=['detail','guide','arrived'].includes(state.view)?'home':state.view==='station'?'real':state.view;const label={home:'路线体验',real:'真实站点',station:'真实站点',facilities:'无障碍设施',saved:'我的收藏',reports:'反馈记录'}[active];return `<aside class="sidebar"><a href="#" data-action="nav" data-view="home" class="brand" aria-label="AccessAI 首页"><img src="assets/favicon.svg" alt=""><span>AccessAI<span style="color:#71946a">.</span></span></a><p class="brand-sub">无障碍出行</p><div class="nav-label">出行工具</div>${nav(active)}<div class="sidebar-foot"><div class="sidebar-note">${icon('leaf')}<strong style="font-size:13px">资料说明</strong><p>路线体验使用虚构数据；真实站点单独列出官方资料和来源。</p><button class="text-btn" data-action="help">关于这个 Demo ${icon('arrow')}</button></div><p class="version">ACCESSAI · DEMO 04</p></div></aside><div class="shell"><header class="topbar"><div class="breadcrumb">无障碍出行 <span>/ &nbsp;${label}</span></div><div class="mobile-brand"><a class="brand" href="#" data-action="nav" data-view="home"><img src="assets/favicon.svg" alt="">AccessAI.</a></div><div class="top-actions"><span class="pill demo">${icon('info')}${['real','station'].includes(state.view)?'公开资料 · 非实时':'路线体验 · 演示数据'}</span><button class="icon-btn desktop-help" data-action="help" aria-label="使用帮助">${icon('info')}</button><button class="icon-btn ${state.settings.large?'on':''}" data-action="settings" aria-label="阅读与无障碍设置">${icon('settings')}</button></div></header><main id="main" class="workspace">${!storageOK?'<p class="storage-warning">本地存储不可用，收藏和反馈仅在本次打开期间保留。</p>':''}${body}<footer class="demo-strip"><span>演示路线为虚构场景；真实站点依据公开资料整理，不提供实时设备状态。</span>${['real','station'].includes(state.view)?'<span>资料整理于 2026-11-17</span>':`<button class="text-btn" data-action="scenarios">${icon('settings')}模拟状态：${scenarios[state.scenario].name}</button>`}</footer></main></div>${nav(active,true)}`}
function map(route=state.route){if(!['A','B'].includes(route))return mapPlan(route);const main=route==='A',bad=state.scenario==='e2';const marker=(x,y,label,ic,id,color='#174e40')=>`<g class="map-interactive" tabindex="0" role="button" aria-label="查看${label}" data-action="facility" data-id="${id}" transform="translate(${x} ${y})"><circle r="22" fill="${color}" stroke="#fff" stroke-width="5"/><g transform="translate(-10 -10) scale(.85)" stroke="white" stroke-width="1.8" fill="none">${paths[ic]}</g><rect x="-38" y="28" width="76" height="26" rx="8" fill="white"/><text y="45" text-anchor="middle" fill="#294c3b" font-size="11">${label}</text></g>`;return `<div class="map-card"><div class="map-heading"><strong>云桥生活圈</strong><span>云桥站 → 星河商场 · 空间示意</span></div><svg class="map-canvas" viewBox="0 0 760 510" role="img" aria-labelledby="map-title" preserveAspectRatio="xMidYMid slice"><title id="map-title">${main?'A出口主路线':'C出口备用路线'}示意图，所有地点均为虚构，不按比例绘制</title><defs><pattern id="grid" width="23" height="23" patternUnits="userSpaceOnUse"><path d="M23 0H0V23" fill="none" stroke="#dfe7d9" stroke-width=".5"/></pattern><filter id="shadow"><feDropShadow dx="0" dy="5" stdDeviation="6" flood-color="#284637" flood-opacity=".1"/></filter></defs><rect width="760" height="510" fill="#edf2e7"/><rect width="760" height="510" fill="url(#grid)"/><path d="M-20 310 770 310M260-10V540M520-10V540M-10 100H780" fill="none" stroke="#dce3d6" stroke-width="59"/><path d="M-20 310 770 310M260-10V540M520-10V540M-10 100H780" fill="none" stroke="#fafbf6" stroke-width="48"/><path d="M-20 310 770 310M260-10V540M520-10V540" fill="none" stroke="#dce3d6" stroke-width="1" stroke-dasharray="8 10"/><rect x="25" y="150" width="177" height="108" rx="18" fill="#e0e8d7" stroke="#d4dfc9"/><rect x="32" y="157" width="160" height="89" rx="13" fill="#e7eddc"/><text x="112" y="211" text-anchor="middle" fill="#8c9b80" font-size="14">云桥公园</text><g fill="#c3d4b6"><circle cx="48" cy="162" r="12"/><circle cx="187" cy="242" r="10"/><circle cx="43" cy="235" r="13"/><circle cx="180" cy="168" r="15"/><circle cx="165" cy="183" r="10"/><circle cx="54" cy="183" r="10"/></g><g fill="#e0e5da" stroke="#d3dccb"><rect x="310" y="23" width="149" height="45" rx="9"/><rect x="573" y="25" width="150" height="43" rx="9"/><rect x="575" y="367" width="152" height="102" rx="10"/><rect x="325" y="379" width="130" height="88" rx="10"/></g><text x="650" y="426" text-anchor="middle" font-size="13" fill="#8a9781">社区服务中心</text><g filter="url(#shadow)"><rect x="320" y="153" width="150" height="104" rx="13" fill="#c2d9c1" stroke="#9fbea0"/><rect x="328" y="160" width="134" height="88" rx="9" fill="#d3e5cd"/><path d="M350 171h26v19h-26m35-19h26v19h-26m35-19h26v19h-26" fill="#e8f2df"/><text x="395" y="217" text-anchor="middle" font-size="19" font-weight="700" fill="#315b41">星河商场</text><text x="395" y="237" text-anchor="middle" font-size="10" letter-spacing="2" fill="#69866b">XINGHE MALL</text></g><rect x="38" y="367" width="164" height="95" rx="14" fill="#e9e2d0" stroke="#d7cdb7"/><text x="120" y="403" text-anchor="middle" fill="#796c51" font-size="18" font-weight="600">云桥站</text><text x="120" y="425" text-anchor="middle" fill="#8c7b5e" font-size="10">站台 B2 · 站厅 B1</text><text x="604" y="297" font-size="11" fill="#94a08b" letter-spacing="5">云 桥 路</text><text x="542" y="165" font-size="11" fill="#94a08b" transform="rotate(90 542 165)" letter-spacing="4">星河步行街</text><path d="M178 380 260 380 260 273 393 273 393 254" fill="none" stroke="${main?'#2c7656':'#9bb28d'}" stroke-width="${main?6:4}" stroke-linecap="round" stroke-linejoin="round" stroke-dasharray="${main?'0':'6 8'}"/><path d="M178 380 230 350 520 350 520 214 471 214" fill="none" stroke="${main?'#a5b898':'#2c7656'}" stroke-width="${main?4:6}" stroke-linecap="round" stroke-linejoin="round" stroke-dasharray="${main?'6 8':'0'}"/>${marker(178,380,'E1 电梯','lift','E1',state.scenario==='e1'?'#ad6b32':'#174e40')}${marker(260,273,'A 出口','lift','E2',bad?'#ad6b32':'#174e40')}${marker(520,350,'C 出口','lift','E3',state.scenario==='e3'?'#ad6b32':main?'#748b66':'#174e40')}${marker(main?393:471,main?254:214,main?'南入口':'东入口','door',main?'south':'east',main&&state.scenario==='southClosed'?'#ad6b32':'#174e40')}<g transform="translate(690 145)" fill="#74836c"><path d="m0-15 7 25-7-5-7 5Z"/><text y="-23" text-anchor="middle" font-size="10">N</text></g></svg><div class="map-key"><span><i></i>当前路线</span><span><i class="alt"></i>备选路线</span><small>非真实地图 · 不按比例</small></div></div>`}
function facilityStatus(f){if(f.id==='wc')return tag('信息不足','warn','info');const fid={south:'entrance-south',east:'entrance-east'}[f.id]||f.id;if(D.scenarios[state.scenario].unavailable.includes(fid))return tag('模拟停用','error','alert');return tag('样例可用','','check')}
function placeCard(f){return `<button class="place-card" data-action="facility" data-id="${f.id}"><img src="assets/${f.asset}.svg" alt="${f.name}场景示意" loading="lazy"><div class="place-copy"><h3>${f.name}</h3><p>${f.sub}</p><div class="tags">${facilityStatus(f)}${tag(f.type==='lift'?'无障碍电梯':f.type==='entrance'?'入口指引':'服务设施')}</div></div></button>`}

function destination(id=state.route){return D.destinations[D.routes[id]?.destination||'mall']}
function routeIds(){return destination().routeIds}
function alternative(){return D.getAlternatives(state.route,state.position,state.scenario)[0]||null}
function mapPlan(id){const r=D.routes[id],d=destination(id);const exit=id==='H'?'C':'A';const lift=id==='H'?'E3':'E2';return `<div class="map-card route-schematic"><div class="map-heading"><strong>${d.name} · 连接示意</strong><span>虚构场景，不按比例绘制</span></div><svg class="map-canvas" viewBox="0 0 760 510" role="img" aria-label="${d.name}路线由站台、站厅、${exit}出口和目的地连接"><rect width="760" height="510" fill="#f3f5f7"/><path d="M100 380H300V250H540V130" fill="none" stroke="#2c7656" stroke-width="7" stroke-linejoin="round"/><g fill="#fff" stroke="#2c7656" stroke-width="4"><circle cx="100" cy="380" r="13"/><circle cx="300" cy="380" r="13"/><circle cx="300" cy="250" r="13"/><circle cx="540" cy="130" r="13"/></g><g fill="#29384b" font-family="inherit" font-size="18"><text x="55" y="422">B2 站台</text><text x="260" y="422">B1 站厅</text><text x="330" y="256">${exit} 出口 · 地面</text><text x="565" y="136">${d.name}</text></g><g fill="#647286" font-family="inherit" font-size="14"><text x="178" y="365">E1 电梯</text><text x="220" y="315">${lift} 电梯</text><text x="555" y="200">${id==='H'?'门诊平层入口':'公园东侧通道'}</text></g></svg><div class="map-key"><span><i></i>演示路线</span><small>只表示连接关系，不提供定位</small></div></div>`}
function realCard(station){return `<button class="real-card" data-action="station" data-id="${station.id}"><header><span class="real-city">${esc(station.city)}</span><span class="tag source-tag">官方资料</span></header><h3>${esc(station.name)}</h3><p class="real-line">${esc(station.lines.join(' / ')||'港铁车站')}</p><div class="real-access"><span>街面电梯</span><strong>${esc(station.streetAccess.map(a=>a.label).join('、'))}</strong></div><p class="source-meta">${esc(station.source.name)} · 状态待确认</p><span class="source-link">查看设施详情 ${icon('arrow')}</span></button>`}
function realSection(){return `<section class="real-section"><div class="section-head"><div><h2>真实站点资料</h2><p>已读取的官方设施信息，运行状态需要另行确认</p></div><button class="text-btn" data-action="nav" data-view="real">全部 ${R.stations.length} 站 ${icon('arrow')}</button></div><div class="real-grid">${[...R.stations].sort((a,b)=>(a.city==='香港'?-1:1)-(b.city==='香港'?-1:1)).slice(0,3).map(realCard).join('')}</div></section>`}
function realStations(){const stations=R.stations.filter(x=>state.city==='all'||x.city===state.city);return `<div class="page-lead"><h1 tabindex="-1">真实站点资料</h1><p>查看电梯所在出口和其他无障碍设施。资料摘录保存在本地，不自动更新。</p></div><div class="notice">${icon('info')}检索日期：${R.retrievedAt}。这不是设施核验时间，也不是设备当前运行状态。</div><div class="filter-row real-filter" aria-label="城市筛选">${[['all','全部城市'],['深圳','深圳'],['香港','香港']].map(([v,l])=>`<button class="filter ${state.city===v?'active':''}" data-action="city" data-city="${v}" aria-pressed="${state.city===v}">${l}</button>`).join('')}</div><div class="real-grid">${stations.map(realCard).join('')}</div><section class="trust-card"><h3>这些资料能回答什么</h3><p>能查看运营方公布的电梯位置和设施配置。完整站内连接、具体尺寸、现场照片和当前运行情况尚未核验，因此不提供基于这些资料的逐步导航。</p></section>`}
function stationDetail(){const st=R.stations.find(x=>x.id===state.realId);if(!st)return realStations();return `<button class="text-btn" data-action="nav" data-view="real">${icon('back')}全部真实站点</button><div class="page-lead"><div class="tags">${tag(esc(st.city))}${tag('官方公开资料')}</div><h1 tabindex="-1">${esc(st.name)}</h1><p>${esc(st.lines.join(' / ')||'港铁车站')} · ${esc(st.summary)}</p></div><div class="two-col station-detail"><section class="panel"><h2>电梯与出入口</h2><div class="station-facts">${st.streetAccess.map(a=>`<article><span class="station-exit">${esc(a.label)}</span><div><h3>街面连接设施</h3><p>${esc(a.detail)}</p></div></article>`).join('')}</div><div class="divider"></div><h3>站厅与站台</h3><p class="station-paragraph">${esc(st.platformAccess)}</p><div class="divider"></div><h3>其他设施</h3><ul class="fact-list">${st.otherFacilities.length?st.otherFacilities.map(f=>`<li>${esc(f)}</li>`).join(''):'<li>本次资料摘录未采录其他设施，不能据此判断现场没有。</li>'}</ul><div class="notice warn">${icon('info')}设施配置不代表现在可以使用。请向运营方确认运行状态、开放条件与所需协助。</div></section><aside><section class="panel"><h2>资料来源</h2><dl class="source-dl"><dt>发布机构</dt><dd>${esc(st.source.name)}</dd><dt>读取方式</dt><dd>${esc(st.source.accessMethod)}</dd><dt>检索日期</dt><dd>${esc(st.retrievedAt)}</dd><dt>原文更新时间</dt><dd>${st.source.publishedAt?esc(st.source.publishedAt):'原文未明确标注'}</dd><dt>实时状态</dt><dd>未接入</dd></dl><a class="btn primary full" href="${esc(st.source.url)}" target="_blank" rel="noopener noreferrer">查看官方原文 ${icon('arrow')}</a><button class="text-btn" data-action="copy-station">${icon('list')}复制资料摘要</button></section><section class="trust-card"><h3>出发前需要确认</h3><ul class="fact-list">${st.unknowns.map(f=>`<li>${esc(f)}</li>`).join('')}</ul><p>没有把示意图、虚构距离或演示核验记录用于这个真实站点。</p></section></aside></div>`}
function copyStation(){const st=R.stations.find(x=>x.id===state.realId);if(!st)return;const text=`${st.city} ${st.name}\n街面设施：${st.streetAccess.map(a=>a.label+'：'+a.detail).join('；')}\n站厅/站台：${st.platformAccess}\n来源：${st.source.name}\n${st.source.url}\n检索日期：${st.retrievedAt}，设备运行状态未接入，非现场核验。`;if(navigator.clipboard?.writeText)navigator.clipboard.writeText(text).then(()=>toast('资料摘要已复制，包含来源和状态说明')).catch(()=>copyFallback(text));else copyFallback(text)}
function copyFallback(text){openModal('复制资料摘要',`<p>选中下面的文字即可复制。</p><textarea readonly aria-label="站点资料摘要" style="min-height:230px">${esc(text)}</textarea>`);dialog.querySelector('textarea').select()}

function routeFeature(id='A'){const r=D.routes[id],d=destination(id);return `<div class="route-feature"><div class="route-visual">${icon(id==='H'?'home':id==='P'?'leaf':'route')}</div><div class="route-content"><h3>云桥站 → ${d.name}</h3><div class="tags">${tag('全程无台阶','','chair')}${tag(r.exit)}</div><div class="meta"><strong>${r.minutes}</strong>分钟 <span>· ${r.distance} 米 · 全程样例估算</span></div></div><button class="icon-btn" data-action="open-route" data-route="${id}" aria-label="查看${id}路线">${icon('arrow')}</button></div>`}
function home(){return `<div class="intro-row"><div><h1 tabindex="-1">出行路线</h1><p class="muted">查入口、找电梯，提前了解通行条件。</p></div><button class="text-btn" data-action="nav" data-view="real">${icon('pin')}查询真实站点</button></div><div class="hero-grid"><section class="welcome-card"><span class="tag">出行需求 · 路线与资料</span><h2>一句话，说清你的出行需求</h2><p>理解通行偏好、查看规划依据，或查询有来源的站点资料。助手页面会显示 AI 的实际连接状态。</p><a class="btn primary full" href="assistant.html" style="margin-top:18px">${icon('message')}一句话规划出行 ${icon('arrow')}</a><div class="home-entry-links"><a class="text-btn" href="navigate.html#demo">在模拟图上选择任意起点</a><a class="text-btn secondary-entry" href="navigate.html">从当前位置出发 <small>查看覆盖范围</small></a></div><form class="search-form" id="search-form" role="search">${icon('search')}<label class="sr-only" for="search">搜索演示地点或真实站点</label><input id="search" name="query" placeholder="搜索商场、医院、公园或真实站名" autocomplete="off" value="${esc(state.query)}"><button aria-label="搜索">${icon('arrow')}</button></form><div class="quick-links"><button data-action="open-route" data-route="A">星河商场</button><button data-action="open-route" data-route="H">社区医院</button><button data-action="open-route" data-route="P">云桥公园</button></div><div class="home-notes"><div>${icon('chair')}路线按全程无台阶需求组织</div><div>${icon('lift')}可体验停运、入口关闭与积水</div><div>${icon('info')}演示路线与真实站点分别标注</div></div><button class="text-btn" data-action="scenarios">切换模拟状态 ${icon('arrow')}</button></section>${map('A')}</div>${state.query?searchResults():''}<section class="destinations-section"><div class="section-head"><div><h2>选择出行场景</h2><p>三类目的地，四条路线。所有体验场景均为虚构。</p></div></div><div class="destination-grid">${Object.values(D.destinations).map(d=>`<button class="destination-card" data-action="open-route" data-route="${d.routeIds[0]}"><img src="${d.asset}" alt="${d.name}虚构场景示意"><div class="destination-copy"><span class="destination-kind">${d.kind}</span><h3>${d.name}</h3><p>${d.summary}</p><div class="destination-bottom"><span>${d.routeIds.length} 条演示路线</span>${icon('arrow')}</div></div></button>`).join('')}</div></section>${realSection()}<section class="places-row"><div class="section-head"><div><h2>演示区域设施</h2><p>查看入口、电梯和资料不足时的提示</p></div><button class="text-btn" data-action="nav" data-view="facilities">查看全部 ${icon('arrow')}</button></div><div class="place-grid">${[facilityCards[1],facilityCards[3],facilityCards[2]].map(placeCard).join('')}</div></section>`}
function searchResults(){const q=state.query.toLowerCase();const fs=facilityCards.filter(f=>(f.name+f.sub).toLowerCase().includes(q));const ds=Object.values(D.destinations).filter(d=>(d.name+d.kind).includes(q));const rs=R.stations.filter(x=>(x.city+x.name).includes(q));return `<section class="result-summary" aria-live="polite"><h2>“${esc(state.query)}”的搜索结果</h2>${ds.map(d=>routeFeature(d.routeIds[0])).join('')}${rs.length?`<div class="real-grid">${rs.map(realCard).join('')}</div>`:''}${fs.length?`<div class="filter-row">${fs.map(f=>`<button class="filter" data-action="facility" data-id="${f.id}">${f.name}</button>`).join('')}</div>`:''}${!fs.length&&!ds.length&&!rs.length?'<p class="muted">暂未找到。可以搜索“医院”“公园”“中环”“老街”或“电梯”。</p>':''}</section>`}
function available(id){if(state.view==='guide'&&state.trip?.routeId===id){const remaining=state.trip.steps.slice(state.trip.confirmed);return remaining.length>0&&remaining.every(step=>!D.scenarios[state.scenario].unavailable.includes(step.facility))}return D.isAvailable(id,state.position,state.scenario)&&D.getRemainingSteps(id,state.position).length>0}
function noRouteReason(){if(state.position==='platform'&&state.scenario==='e1')return 'E1 是站台连接站厅的共用电梯，当前模拟停运。两条商场路线都受影响，医院与公园路线也无法从站台出发。';if(['mall','hospital','park'].includes(state.position))return '你已确认到达目的地，可以开始新的行程。';if(state.position==='streetA'&&state.scenario==='southClosed')return '南入口关闭，当前没有从 A 出口街面连接东入口的已核验通道，不能直接改道。';if(state.route==='P'&&state.scenario==='rain')return '公园通道模拟积水，当前没有已核验的备用路径。';if(state.route==='H'&&state.scenario==='e3')return '医院路线需要 E3 电梯，目前模拟停运，当前没有通往医院的已核验备用路径。';return '当前没有从你确认的位置出发、通往该目的地的可用路线。'}
function routeStops(steps){return `<ol class="route-stops">${steps.map((s,i)=>`<li><span class="stop-num">${i+1}</span><div><strong>${s.title}</strong><p>${s.floor} · ${s.landmark}</p></div></li>`).join('')}</ol>`}
function detail(){const r=D.routes[state.route],d=destination(),ok=available(state.route),steps=D.getRemainingSteps(state.route,state.position);return `<button class="text-btn" data-action="nav" data-view="home">${icon('back')}返回出行路线</button><div class="page-lead"><span class="tag">虚构路线体验</span><h1 tabindex="-1">云桥站 → ${d.name}</h1><p>${d.summary}</p></div><div class="two-col"><section class="panel"><div class="field"><label for="position" class="form-label">手动确认出发位置</label><select id="position" data-change="position">${Object.entries(positions).filter(([k])=>!['mall','hospital','park'].includes(k)).map(([k,v])=>`<option value="${k}" ${state.position===k?'selected':''}>${v}</option>`).join('')}</select><p class="step-mini">选择你已确认的地标。本演示不使用定位。</p></div><div class="form-label">${d.routeIds.length>1?'可选路线':'已收录路线'}</div>${d.routeIds.map(id=>{const v=D.routes[id],usable=available(id);return `<button class="route-choice ${state.route===id?'selected':''} ${!usable?'unavailable':''}" data-action="select-route" data-route="${id}" aria-pressed="${state.route===id}"><div class="route-choice-top"><h3>${v.name}</h3><span><strong>${v.minutes}</strong><small> 分钟</small></span></div><p>${v.exit} → ${v.entrance} · 全程 ${v.distance} 米（样例）</p><div class="tags">${usable?tag('符合无台阶需求','','chair'):tag('当前出发条件下不可用','warn','alert')}${tag(id==='A'?'距离较短':id==='B'?'可绕开 E2':'单条演示路线')}</div></button>`}).join('')}<div class="divider"></div>${!ok?`<div class="notice danger">${icon('alert')}<div><strong>这条路线目前无法开始</strong>${alternative()?'可选择另一条通往相同目的地的路线。':noRouteReason()}</div></div>`:`<div class="notice">${icon('info')}<div><strong>适用条件 · 演示设定</strong>${d.id==='hospital'?'到达门诊平层入口后，还需向服务台确认具体就诊楼层与院内路线。':d.id==='park'?'经公园东入口进入。通道宽度、坡度和路面情况均为演示设定。':'样例使用电梯、宽闸机和平层入口，商场入口演示开放时间 10:00–22:00。'}具体尺寸未实测。</div></div>`}<dl class="metadata"><div><dt>到达入口</dt><dd>${r.entrance}</dd></div><div><dt>通行需求</dt><dd>全程无台阶</dd></div><div><dt>资料状态</dt><dd>虚构演示</dd></div></dl><div class="action-row">${btn(`开始图文引导 ${icon('arrow')}`,'start','primary grow',!ok?'disabled':'')}<button class="icon-btn ${state.saved.includes(state.route)?'on':''}" data-action="save" data-route="${state.route}" aria-label="${state.saved.includes(state.route)?'取消收藏':'收藏路线'}" aria-pressed="${state.saved.includes(state.route)}">${icon('heart')}</button></div>${!ok?btn('查看协助说明','assist','soft full','style="margin-top:12px"'):''}</section><aside class="sticky-map"><div>${map()}<section class="trust-card"><h3>路径步骤</h3>${steps.length?routeStops(steps):'<p>当前位置与所选路线没有已知的后续连接。</p>'}</section></div><section class="trust-card"><h3>数据说明</h3><p>该路线及图像均为虚构示例。距离、时间和核验记录不能用于实际出行。真实站点资料可以在“真实站点”页面单独查看。</p><button class="text-btn" data-action="nav" data-view="real">查询真实站点 ${icon('arrow')}</button></section></aside></div>`}
function guidance(){const t=state.trip;if(!t){state.view='detail';return detail()}const s=t.steps[t.index],ok=available(t.routeId);const altId=alternative();return `<div class="section-head"><div><div class="eyebrow">ONE STEP AT A TIME</div><h1 tabindex="-1" style="font-size:27px">分步引导</h1></div><button class="text-btn" data-action="leave">退出引导 ${icon('close')}</button></div><div class="progress-meta"><span>${D.routes[t.routeId].entrance} · ${t.routeId} 路线</span><span>已完成 ${t.confirmed} / ${t.steps.length} 步</span></div><div class="progress-track" role="progressbar" aria-label="路线步骤进度" aria-valuenow="${t.confirmed}" aria-valuemin="0" aria-valuemax="${t.steps.length}"><span style="width:${100*t.confirmed/t.steps.length}%"></span></div>${!ok?`<div class="notice danger" style="margin-bottom:20px">${icon('alert')}<div><strong>前方通行受阻 · 模拟状态</strong>${altId&&available(altId)?'当前路线有设施停用或入口关闭，可从已确认的位置切换至同目的地的备用路线。':noRouteReason()}<div class="action-row">${altId&&available(altId)?btn('查看并切换备用路线','reroute','warning'):btn('查看协助方式','assist','warning')}</div></div></div>`:''}<div class="two-col guide-layout"><section class="guide-card"><div class="guide-art"><img src="${s.asset}" alt="${esc(s.landmark)}的原创场景示意"><span class="floor-label">${s.floor}</span></div><div class="guide-body"><div class="eyebrow">STEP ${String(t.index+1).padStart(2,'0')} / ${String(t.steps.length).padStart(2,'0')}</div><h2 tabindex="-1">${s.title}</h2><p class="guide-instruction">${s.instruction}</p><div class="landmark">${icon('pin')}<span>认一认地标：${s.landmark}</span></div><p class="step-mini">已确认位置：${positions[state.position]} · 手动确认</p><div class="guide-buttons">${btn(`${icon('back')}上一步`,'prev','',t.index===0?'disabled':'')}${btn(`${t.index<t.confirmed?'返回下一步':t.index===t.steps.length-1?'确认到达目的地':'我已到达，下一步'} ${icon('arrow')}`,'next','primary',!ok?'disabled':'')}</div><div class="guide-tools"><button class="text-btn" data-action="speak" id="speak-btn">${icon(state.speaking?'stop':'sound')}${state.speaking?'停止朗读':'朗读这一步'}</button><button class="text-btn" data-action="report">${icon('message')}找不到 / 遇到问题</button></div></div></section><aside class="guide-side">${map(t.routeId)}<section class="panel"><h3>接下来怎么走</h3><p class="step-mini">已完成步骤可以回看</p><div style="margin-top:12px">${t.steps.map((step,i)=>`<button class="step-button ${i===t.index?'current':''}" data-action="step" data-index="${i}" ${i>t.confirmed?'disabled':''} ${i===t.index?'aria-current="step"':''}><span class="stop-num">${i<t.confirmed?icon('check'):i+1}</span><div><strong style="font-size:12px">${step.title}</strong><p>${step.floor}</p></div></button>`).join('')}</div><div class="divider"></div><button class="text-btn" data-action="scenarios">${icon('settings')}切换演示场景</button></section></aside></div>`}
function arrived(){const d=destination();return `<section class="panel arrived"><div class="success-icon">${icon('check')}</div><h1 tabindex="-1">已抵达${d.name}</h1><p class="muted" style="margin-top:10px">${D.routes[state.route].entrance} · 演示行程完成</p><img src="${d.asset}" alt="${d.name}虚构入口示意"><div class="notice" style="text-align:left">${icon('info')}${d.id==='hospital'?'已到达门诊入口。就诊楼层、院内电梯及协助需求仍需向医院服务台确认。':'演示行程已完成。真实出行前，需要重新确认设施与通行条件。'}</div><h3 style="margin-top:24px">指引是否清楚？</h3><div class="rating-row">${['清楚好找','有些地方不清楚','需要更多帮助'].map((v,i)=>`<button class="btn small" data-action="rate" data-rating="${i}" aria-pressed="${state.rating===i}">${v}</button>`).join('')}</div><div class="action-row" style="justify-content:center;flex-wrap:wrap">${btn('收藏这条路线','save','soft',`data-route="${state.route}"`)}${btn('重新规划','new-trip')}</div></section>`}
function facilities(){const list=facilityCards.filter(f=>state.filter==='all'||f.type===state.filter);return `<div class="page-lead"><div class="eyebrow">ACCESS AROUND YOU</div><h1 tabindex="-1">演示区域设施</h1><p>查看演示区域内的电梯、入口与服务设施。</p></div><div class="filter-row" role="group" aria-label="设施类别">${[['all','全部设施'],['lift','无障碍电梯'],['entrance','商场入口'],['service','服务设施']].map(([v,l])=>`<button class="filter ${v===state.filter?'active':''}" data-action="filter" data-filter="${v}" aria-pressed="${v===state.filter}">${l}</button>`).join('')}</div><div class="facility-grid">${list.map(placeCard).join('')}</div><div class="notice" style="margin-top:24px">${icon('info')}“样例可用”是演示设定；“信息不足”表示缺少可判断的资料。设施存在不代表整条路径可以通过。</div>`}
function saved(){return `<div class="page-lead"><div class="eyebrow">YOUR FAMILIAR PATHS</div><h1 tabindex="-1">收藏的路线</h1><p>收藏保存在当前浏览器。出发前仍需查看最新通行条件。</p></div>${state.saved.length?`<div class="saved-list">${state.saved.map(id=>`<section>${routeFeature(id)}<button class="text-btn danger-btn" data-action="save" data-route="${id}">${icon('trash')}移除收藏</button></section>`).join('')}</div>`:`<div class="empty">${icon('heart')}<h2>还没有收藏路线</h2><p>在路线详情中点击爱心，下次就能更快找到。</p>${btn('探索第一条路线','open-route','primary','data-route="A"')}</div>`}`}
function reports(){return `<div class="page-lead"><div class="eyebrow">SMALL NOTES, BETTER JOURNEYS</div><h1 tabindex="-1">问题反馈记录</h1><p>记录难找的位置或设施问题。演示反馈仅保存在本机，不会提交给运营方。</p></div><div class="action-row" style="margin-bottom:22px">${btn(`${icon('message')}记录一个问题`,'report')}${state.reports.length?btn(`${icon('download')}导出记录`,'export',''):''}</div>${state.reports.length?`<div class="feedback-list">${state.reports.map(f=>`<article class="feedback-card"><header><h3>${esc(f.type)}</h3>${tag('演示记录 · 待核实','warn')}</header><p>${esc(f.note||'未填写补充说明')}</p><footer>${esc(f.location)} · ${esc(f.time)} · 仅保存在本机</footer><button class="text-btn danger-btn" data-action="delete-report" data-id="${esc(f.id)}">${icon('trash')}删除这条记录</button></article>`).join('')}</div>`:`<div class="empty">${icon('message')}<h2>暂无反馈记录</h2><p>遇到电梯停运、入口关闭或指引不清楚，都可以在这里记录。</p></div>`}`}
function render(){const priorAction=document.activeElement?.dataset?.action;const priorIndex=document.activeElement?.dataset?.index;document.body.classList.toggle('in-guide',state.view==='guide');document.body.classList.toggle('large-text',state.settings.large);const views={home,detail,guide:guidance,arrived,facilities,saved,reports,real:realStations,station:stationDetail};app.innerHTML=layout(views[state.view]());document.title=`${{home:'出行路线',real:'真实站点',station:'站点详情',detail:'规划路线',guide:'分步引导',arrived:'已经抵达',facilities:'无障碍设施',saved:'我的收藏',reports:'反馈记录'}[state.view]} · AccessAI`;if(state.view==='guide'&&state.trip){const step=state.trip.steps[state.trip.index];const status=document.getElementById('guide-announcement');if(status)status.textContent=`第 ${state.trip.index+1} 步，共 ${state.trip.steps.length} 步。${step.title}。${step.instruction}`;requestAnimationFrame(()=>{if(state.view!=='guide'||dialog.open)return;let target=['next','prev','speak','step'].includes(priorAction)?app.querySelector(`[data-action="${priorAction}"]${priorAction==='step'?`[data-index="${Number(priorIndex)}"]`:''}`):null;if(!target||target.disabled)target=app.querySelector('.guide-body h2');target?.focus({preventScroll:true})})}}
let modalReturnFocus=null;
function openModal(title,html){modalReturnFocus=document.activeElement;dialog.innerHTML=`<header class="modal-head"><h2 id="dialog-title">${title}</h2><button class="icon-btn" data-action="close" aria-label="关闭窗口">${icon('close')}</button></header><div class="modal-body">${html}</div>`;if(!dialog.open)dialog.showModal()}
function closeModal(){dialog.close();if(modalReturnFocus?.isConnected)modalReturnFocus.focus()}
function facilityModal(id){const f=facilityCards.find(x=>x.id===id);if(!f)return;openModal(f.name,`<img src="assets/${f.asset}.svg" alt="${f.name}场景示意"><div class="tags" style="margin-bottom:15px">${facilityStatus(f)}${f.tags.map(t=>tag(t)).join('')}</div><p>${f.detail}</p><div class="notice">${icon('info')}资料来源：AccessAI 虚构样例。日期为演示记录，未进行现场核验。尺寸与可用性不能用于真实通行判断。</div>${id==='wc'?btn('了解资料不足的含义','help','soft full'):btn('从站台查看相关路线','facility-route','primary full',`data-route="${id==='entrance-hospital'?'H':id==='entrance-park'||id==='path-park'?'P':id==='E3'||id==='east'?'B':'A'}"`)}`)}
function scenarioModal(){openModal('选择一个演示场景',`<p>这些开关仅作用于虚构路线，不会改变真实站点资料。当前确认位置：${positions[state.position]}。</p><div class="scenario-list">${Object.entries(scenarios).map(([id,s])=>`<button class="scenario-btn ${state.scenario===id?'selected':''}" data-action="scenario" data-scenario="${id}" aria-pressed="${state.scenario===id}">${icon(s.icon)}<span><strong>${s.name}</strong><small>${s.desc}</small></span></button>`).join('')}</div><div class="notice" style="margin-top:18px">${icon('info')}若已通过 E1 到达站厅，再模拟 E1 停运不会阻断后续路段。体验“无可用路线”可先重置行程。</div><div class="modal-actions">${btn('重置演示行程','reset','soft')}${btn('返回体验','close')}</div><p class="download-note">重置行程会恢复设施正常，并保留收藏、反馈与阅读设置。</p>`)}
function reportModal(){openModal('记录遇到的问题',`<p>当前位置：${positions[state.position]}。反馈保存后标记为待核实，不会直接改变设施状态。</p><form id="report-form" class="feedback-form"><fieldset style="border:0;padding:0;margin:0"><legend class="form-label">问题类型</legend><div class="radio-grid">${['电梯停运','入口关闭','位置不清楚','其他问题'].map((t,i)=>`<label><input type="radio" name="type" value="${t}" ${i===0?'checked':''}>${t}</label>`).join('')}</div></fieldset><label class="form-label" for="note">补充说明（选填）</label><textarea id="note" name="note" maxlength="500" placeholder="例如：指示牌不明显，找电梯时绕了一圈。"></textarea><p class="download-note">最多 500 字。请勿填写个人身份、联系方式或健康信息。</p><button class="btn primary full" type="submit">保存到本机演示记录</button></form>`)}
function helpModal(){openModal('关于 AccessAI',`<p>无障碍出行。AccessAI 探索如何用清晰的设施信息与图文指引，帮助轮椅使用者完成出行的最后一段。</p><ol class="help-list"><li><strong>先看路线。</strong>选择商场、医院或公园，手动确认你在站台、站厅还是街面。</li><li><strong>再认地标。</strong>查看楼层、示意图片与方向。到达后点击“我已到达”。</li><li><strong>受阻时有下一步。</strong>在演示场景中模拟电梯停运、入口关闭或积水，查看改道和协助提示。</li></ol><div class="notice warn">${icon('info')}路线体验中的地点、图片和通行条件为虚构。另有来自官方网页的真实站点资料，单独标注来源与检索日期。未接入实时设备状态；新规划页可主动获取浏览器定位，但暂未接入对应的真实路网。</div><p>信息不足意味着无法判断是否适合通行。实际产品需要现场测量、用户验证与持续维护。核心界面与插图均可离线打开；语音取决于浏览器是否提供中文语音。</p>${btn('开始体验','close','primary full')}`)}
function settingsModal(){openModal('阅读与无障碍设置',`<p>按你的习惯调整阅读体验。设置保存在当前浏览器。</p><label class="toggle-row"><span><strong>大字阅读</strong><small>放大说明文字、按钮和引导内容</small></span><input type="checkbox" id="large-toggle" ${state.settings.large?'checked':''}></label><div class="toggle-row"><span><strong>语音朗读</strong><small>在分步引导中点击“朗读这一步”</small></span>${icon('sound')}</div><p style="margin-top:20px">支持键盘操作、读屏标签和系统减少动态效果设置。地图同时提供文字路线，状态同时使用文字与图标。</p>${btn('完成','close','primary full')}`)}
function assistModal(){openModal('站务协助 · 演示流程',`<div class="notice warn">${icon('alert')}目前无法提供从当前确认位置出发的完整通行保证。请先在安全位置停留并确认现场情况。</div><ol class="help-list"><li>寻找站台或站厅的服务台、工作人员或求助装置。</li><li>说明你的位置、需要前往的出口，以及哪部电梯不可用。</li><li>由工作人员确认是否有其他通道或可提供的协助。</li></ol><p>这是协助流程示例。本 Demo 没有真实联系电话，也不会呼叫工作人员。医院、公园场景请联系对应场所的服务人员。</p>${btn('我了解了','close','primary full')}`)}
function startTrip(id=state.route){if(!available(id)){toast('当前路线不可开始，请检查出发位置和设施状态');return}stopSpeech();state.route=id;state.trip={routeId:id,steps:D.getRemainingSteps(id,state.position),index:0,confirmed:0};go('guide')}
function rerouteModal(){const id=alternative();if(!id||!available(id)){assistModal();return}const r=D.routes[id];openModal('切换路线',`<div class="notice warn">${icon('route')}已确认位置：${positions[state.position]}。只生成该位置之后的剩余指引。</div><h3>${r.name}</h3><p>${r.exit} → ${r.entrance}。完整路线样例约 ${r.distance} 米 / ${r.minutes} 分钟，剩余时间未单独估算。</p>${routeStops(D.getRemainingSteps(id,state.position))}${btn('切换并继续引导','confirm-reroute','primary full',`data-route="${id}"`)}`)}
function speak(){if(!('speechSynthesis'in window)||!('SpeechSynthesisUtterance'in window)){toast('当前浏览器不支持语音，请查看图文指引');return}if(state.speaking){stopSpeech();updateSpeak();return}const s=state.trip.steps[state.trip.index];const voices=window.speechSynthesis.getVoices().filter(v=>/^zh/i.test(v.lang)&&v.localService);if(!voices.length){toast('未检测到本地中文语音，请使用文字指引或安装系统中文语音包');return}const u=new SpeechSynthesisUtterance(`${s.floor}。${s.title}。${s.instruction}。地标：${s.landmark}`);u.voice=voices[0];u.lang='zh-CN';u.rate=.9;u.onend=()=>{state.speaking=false;updateSpeak()};u.onerror=()=>{state.speaking=false;updateSpeak();toast('语音未能播放，图文指引仍可使用')};state.speaking=true;window.speechSynthesis.speak(u);updateSpeak()}
function updateSpeak(){const b=document.querySelector('#speak-btn');if(b)b.innerHTML=icon(state.speaking?'stop':'sound')+(state.speaking?'停止朗读':'朗读这一步')}
function reset(){stopSpeech();state.position='platform';state.route='A';state.scenario='normal';state.trip=null;state.rating=null;closeModal();go('home');toast('演示行程已重置，收藏与反馈仍保留')}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el||el.disabled)return;e.preventDefault();const a=el.dataset.action,id=el.dataset.route;switch(a){case'nav':go(el.dataset.view);break;case'station':state.realId=el.dataset.id;go('station');break;case'city':state.city=el.dataset.city;render();break;case'copy-station':copyStation();break;case'open-route':state.route=id||'A';if(['mall','hospital','park'].includes(state.position))state.position='platform';go('detail');break;case'select-route':state.route=id;render();break;case'facility-route':state.position='platform';state.route=id;closeModal();go('detail');break;case'start':startTrip();break;case'prev':stopSpeech();state.trip.index=Math.max(0,state.trip.index-1);render();break;case'step':stopSpeech();state.trip.index=Number(el.dataset.index);render();break;case'next':{const t=state.trip;if(!available(t.routeId))return;stopSpeech();if(t.index===t.confirmed){state.position=t.steps[t.index].nodeTo;t.confirmed++}if(t.index<t.steps.length-1){t.index++;render()}else{state.rating=null;go('arrived')}break}case'leave':openModal('暂时退出引导？',`<p>会保留你已确认的位置，返回路线页后可以从该位置重新开始。</p><div class="modal-actions">${btn('继续引导','close','soft')}${btn('返回路线页','confirm-leave')}</div>`);break;case'confirm-leave':closeModal();go('detail');break;case'save':{const rid=id||state.route;const at=state.saved.indexOf(rid);if(at<0)state.saved.push(rid);else state.saved.splice(at,1);const kept=persist('saved',state.saved);render();toast((at<0?'已收藏路线':'已移除收藏')+(kept?'':' · 仅本次打开有效'));break}case'facility':facilityModal(el.dataset.id);break;case'filter':state.filter=el.dataset.filter;render();break;case'filter-link':state.filter=el.dataset.filter;go('facilities');break;case'close':closeModal();break;case'help':helpModal();break;case'settings':settingsModal();break;case'scenarios':scenarioModal();break;case'scenario':stopSpeech();state.scenario=el.dataset.scenario;closeModal();render();toast('已切换模拟状态：'+scenarios[state.scenario].name);break;case'report':reportModal();break;case'reroute':rerouteModal();break;case'confirm-reroute':closeModal();startTrip(id);toast('已从确认位置切换路线');break;case'assist':assistModal();break;case'speak':speak();break;case'reset':reset();break;case'new-trip':state.position='platform';state.trip=null;state.rating=null;go('detail');break;case'rate':{state.rating=Number(el.dataset.rating);const r={id:Date.now().toString(36),type:'指引体验：'+['清楚好找','有些地方不清楚','需要更多帮助'][state.rating],note:'完成虚构演示路线后的体验评价。',location:positions[state.position],time:new Date().toLocaleString('zh-CN')};state.reports.unshift(r);state.reports=state.reports.slice(0,100);const kept=persist('reports',state.reports);render();toast(kept?'感谢反馈，已保存到本机演示记录':'反馈仅在本次打开期间保留');break}case'delete-report':openModal('删除这条演示记录？',`<p>只会删除当前浏览器中的这条反馈。</p><div class="modal-actions">${btn('保留','close','soft')}${btn('删除记录','confirm-delete','',`data-id="${esc(el.dataset.id)}"`)}</div>`);break;case'confirm-delete':state.reports=state.reports.filter(r=>r.id!==el.dataset.id);persist('reports',state.reports);closeModal();render();toast('记录已删除');break;case'export':{const blob=new Blob([JSON.stringify({notice:'AccessAI 虚构场景，本机演示反馈，未经核实',exportedAt:new Date().toISOString(),reports:state.reports},null,2)],{type:'application/json;charset=utf-8'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='accessai-demo-feedback.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('演示反馈已导出');break}}});
document.addEventListener('change',e=>{if(e.target.matches('[data-change="position"]')){state.position=e.target.value;state.trip=null;if(!available(state.route)&&alternative())state.route=alternative();render()}if(e.target.id==='large-toggle'){state.settings.large=e.target.checked;persist('settings',state.settings);render()}});
document.addEventListener('submit',e=>{if(e.target.id==='search-form'){e.preventDefault();state.query=new FormData(e.target).get('query').trim().slice(0,80);if(!state.query){toast('请输入地点或设施名称');return}render();document.querySelector('.result-summary')?.scrollIntoView({block:'nearest',behavior:'smooth'})}if(e.target.id==='report-form'){e.preventDefault();const f=new FormData(e.target);state.reports.unshift({id:Date.now().toString(36),type:String(f.get('type')),note:String(f.get('note')).trim().slice(0,500),location:positions[state.position],time:new Date().toLocaleString('zh-CN')});state.reports=state.reports.slice(0,100);const kept=persist('reports',state.reports);closeModal();render();toast(kept?'已保存到本机演示记录 · 待核实':'已记录，仅在本次打开期间保留')}});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('svg [role="button"]')){e.preventDefault();e.target.dispatchEvent(new MouseEvent('click',{bubbles:true}))}});
dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal()}});
window.addEventListener('pagehide',stopSpeech);
if('speechSynthesis'in window)window.speechSynthesis.getVoices();
if(new URLSearchParams(window.location.search).get('view')==='real')state.view='real';
render();
})();
